//! Report-only audit for natural file commands. Uses independent seed/variant
//! expectations and the compiled parser plus planner; no plan is confirmed.
use crate::{fsx::{self, Roots}, history::History, model::Action, parse::parse, plan::{Planner,Planned,Stop}};
use serde_json::{Value,json};
use std::{collections::HashMap,fs,path::PathBuf};

const OUT: &str = "../../docs/testing/luna-command-audit-fixed-2026-11-10.jsonl";
fn path(s:&str)->PathBuf { PathBuf::from(env!("CARGO_MANIFEST_DIR")).join(s) }
fn action(a:&Action)->String { match a { Action::Move{from,to}=>format!("move:{}:{}",from.file_name().unwrap().to_string_lossy(),to.parent().and_then(|p|p.file_name()).unwrap_or_default().to_string_lossy()), Action::Copy{from,to}=>format!("copy:{}:{}",from.file_name().unwrap().to_string_lossy(),to.parent().and_then(|p|p.file_name()).unwrap_or_default().to_string_lossy()), Action::Rename{path,new_name}=>format!("rename:{}:{new_name}",path.file_name().unwrap().to_string_lossy()), Action::Trash{path}=>format!("trash:{}",path.file_name().unwrap().to_string_lossy()), other=>serde_json::to_value(other).unwrap()["kind"].as_str().unwrap_or("other").into() } }
fn fixture()->(tempfile::TempDir,Roots){ let d=tempfile::tempdir().unwrap(); let h=fsx::canonical(d.path()); for f in ["Desktop","Downloads","Documents","Pictures","Screenshots","Documents/Dev","Toggle Wars","Invoices","Backup"] {fs::create_dir_all(h.join(f)).unwrap();} for f in ["Downloads/report.pdf","Downloads/notes.txt","Downloads/Notes from Monday.pdf","Downloads/combined.pdf","Downloads/a.pdf","Downloads/b.pdf","Documents/draft-plan.txt","Pictures/photo.jpg","Pictures/shot.png","Screenshots/shot.png","Documents/Dev/Project Plan.pdf"] {fs::write(h.join(f),b"placeholder bytes").unwrap();} let extras=[h.join("Documents/Dev"),h.join("Backup"),h.join("Invoices")]; (d,Roots::new(&h,Some(h.join("Screenshots")),&extras)) }
fn canon(v:Value)->Value { match v {Value::Object(m)=>Value::Object(m.into_iter().filter(|(_,v)|!v.is_null()).map(|(k,v)|{let v=if (k=="folder"||k=="to")&&v.as_str().is_some_and(|s|["downloads","documents","desktop","pictures","screenshots"].contains(&s.to_ascii_lowercase().as_str())) {json!(v.as_str().unwrap().to_ascii_lowercase())}else{canon(v)};(k,v)}).collect()),Value::Array(a)=>Value::Array(a.into_iter().map(canon).collect()),x=>x} }
#[test] #[ignore]
fn luna_command_audit_report(){
 let seedpath=path("../../docs/testing/paraphrase-audit-2026-11-09/seeds.jsonl");
 let variantpath=path("../../docs/testing/paraphrase-audit-2026-11-09/variants.txt");
 let seeds:HashMap<String,(String,Value)>=fs::read_to_string(seedpath).unwrap().lines().map(|l|{let v:Value=serde_json::from_str(l).unwrap();(v["id"].as_str().unwrap().into(),(v["command"].as_str().unwrap().into(),v["expect"].clone()))}).collect();
 let mut cases:Vec<(String,String,Value,String)>=Vec::new();
 for line in fs::read_to_string(variantpath).unwrap().lines().filter(|l|!l.starts_with('#')&&!l.trim().is_empty()) {
  let p:Vec<_>=line.split(" | ").map(str::trim).collect();
  let (expected,axis)=if p[0].starts_with('N') { (json!("!"),"negative".to_string()) }
   else if p[0].starts_with('A') { (json!("?"),"ambiguous".to_string()) }
   else { let (seedcmd,seedexp)=&seeds[p[1]]; let e=if p[4]=="-" {seedexp.clone()} else {serde_json::from_str(p[4]).unwrap()}; (e,format!("variant_of:{} ({})",seedcmd,p[2])) };
  let intent=expected["intent"].as_str().unwrap_or("");
  if expected=="!" || expected=="?" || ["list","count","move","copy","rename","trash","zip","merge_pdf","images_to_pdf","split_pdf","extract_pages"].contains(&intent) { cases.push((p[0].into(),p[3].into(),expected,axis)); }
 }
 // Additional natural-language coverage: reordered scope/name qualifiers, spoken names,
 // output names, destination prepositions, and distinct action families.
 let extra=[
 ("X001","show me files in Documents/Dev called Project Plan.pdf",json!({"intent":"list","src":{"kind":"item","name":"Project Plan.pdf","folder":"Documents/Dev"}})),
 ("X002","list the files named Project Plan.pdf inside Documents/Dev",json!({"intent":"list","src":{"kind":"item","name":"Project Plan.pdf","folder":"Documents/Dev"}})),
 ("X003","count files containing plan in Documents/Dev",json!({"intent":"count","src":{"kind":"set","folder":"Documents/Dev","filter":{"type":"files","nameContains":"plan"}}})),
 ("X004","show PDFs from Documents/Dev",json!({"intent":"list","src":{"kind":"set","folder":"Documents/Dev","filter":{"type":"pdfs"}}})),
 ("X005","move Project Plan.pdf from Documents/Dev into Backup",json!({"intent":"move","src":{"kind":"item","name":"Project Plan.pdf","folder":"Documents/Dev"},"to":"Backup"})),
 ("X006","copy the file called Project Plan.pdf in Documents/Dev over to Backup",json!({"intent":"copy","src":{"kind":"item","name":"Project Plan.pdf","folder":"Documents/Dev"},"to":"Backup"})),
 ("X007","rename Project Plan.pdf in Documents/Dev to Project Plan final.pdf",json!({"intent":"rename","src":{"kind":"item","name":"Project Plan.pdf","folder":"Documents/Dev"},"new_name":"Project Plan final.pdf"})),
 ("X008","trash the file named Project Plan.pdf from Documents/Dev",json!({"intent":"trash","src":{"kind":"item","name":"Project Plan.pdf","folder":"Documents/Dev"}})),
 ("X009","zip the files in Documents/Dev into Toggle Wars.zip",json!({"intent":"zip","src":{"kind":"set","folder":"Documents/Dev","filter":{"type":"files"}},"output":"Toggle Wars.zip"})),
 ("X010","turn the images in Pictures into a PDF called vacation.pdf",json!({"intent":"images_to_pdf","src":{"kind":"set","folder":"Pictures","filter":{"type":"images"}},"output":"vacation.pdf"})),
 ];
 for (id,cmd,exp) in extra {cases.push((id.into(),cmd.into(),exp,"additional targeted phrase".into()));}
 // 120 fresh phrases (not replayed controls): name/scope ordering, spoken
 // qualifiers, destination prepositions, and output naming across file actions.
 let names=["Project Plan.pdf","draft-plan.txt","Notes from Monday.pdf"];
 let mut fresh=0usize;
 let list_forms=["show {n} in Documents/Dev","list {n} from Documents/Dev","find the file called {n} inside Documents/Dev","show me the file named {n} under Documents/Dev","in Documents/Dev show {n}","inside Documents/Dev list the file {n}","what files are named {n} in Documents/Dev","display {n} located in Documents/Dev","look for {n} within Documents/Dev","find {n} in the Documents/Dev folder","show the file in Documents/Dev called {n}","list the file in Documents/Dev named {n}"];
 for n in names { for (j,f) in list_forms.iter().enumerate(){fresh+=1;cases.push((format!("F{fresh:03}"),f.replace("{n}",n),json!({"intent":"list","src":{"kind":"item","name":n,"folder":"Documents/Dev"}}),format!("fresh_list_order_{j}")));}}
 let count_forms=["count files in Documents/Dev","how many files are in Documents/Dev","count the files inside Documents/Dev","tell me the number of files in Documents/Dev","how many items does Documents/Dev contain","count everything in Documents/Dev","give me a file count for Documents/Dev","number of files under Documents/Dev","count files located in Documents/Dev","how many files does the Documents/Dev folder have","count all files from Documents/Dev","what is the file count in Documents/Dev"];
 for (j,f) in count_forms.iter().enumerate(){fresh+=1;cases.push((format!("F{fresh:03}"),(*f).into(),json!({"intent":"count","src":{"kind":"set","folder":"Documents/Dev","filter":{"type":"files"}}}),format!("fresh_count_{j}")));}
 let action_forms=["{v} {n} from Documents/Dev to Backup","{v} the file named {n} in Documents/Dev into Backup","{v} {n} inside Documents/Dev over to Backup","in Documents/Dev {v} the file called {n} to Backup","{v} the Documents/Dev file {n} into the Backup folder","{v} {n} located in Documents/Dev across to Backup","{v} {n} from the Documents/Dev folder into Backup","{v} the file in Documents/Dev called {n} to the Backup folder","{v} {n} within Documents/Dev over into Backup","{v} {n} in Documents/Dev and put it in Backup","{v} {n} under Documents/Dev to Backup","{v} the file named {n} from Documents/Dev and place it in Backup"];
 for (verb,intent) in [("move","move"),("copy","copy")] { for n in names {for (j,f) in action_forms.iter().enumerate(){fresh+=1;let cmd=f.replace("{v}",verb).replace("{n}",n);let expected=json!({"intent":intent,"src":{"kind":"item","name":n,"folder":"Documents/Dev"},"to":"Backup"});cases.push((format!("F{fresh:03}"),cmd,expected,format!("fresh_{intent}_order_{j}")));}}}
 let trash_forms=["trash {n} from Documents/Dev","trash the file named {n} in Documents/Dev","send {n} from Documents/Dev to the Trash","delete the file called {n} inside Documents/Dev","remove {n} from the Documents/Dev folder","put the Documents/Dev file {n} in Trash","trash the file in Documents/Dev called {n}","delete {n} located in Documents/Dev","move {n} from Documents/Dev to Trash","throw away {n} inside Documents/Dev","discard the file named {n} from Documents/Dev","remove the file called {n} in Documents/Dev"];
 for n in names {for (j,f) in trash_forms.iter().enumerate(){fresh+=1;cases.push((format!("F{fresh:03}"),f.replace("{n}",n),json!({"intent":"trash","src":{"kind":"item","name":n,"folder":"Documents/Dev"}}),format!("fresh_trash_{j}")));}}
 let rename_forms=["rename {n} in Documents/Dev to Final Plan.pdf","rename the file named {n} inside Documents/Dev as Final Plan.pdf","change {n} from Documents/Dev to Final Plan.pdf","call {n} in Documents/Dev Final Plan.pdf","give {n} inside Documents/Dev the name Final Plan.pdf","rename the Documents/Dev file {n} to Final Plan.pdf","in Documents/Dev rename {n} as Final Plan.pdf","change the name of {n} in Documents/Dev to Final Plan.pdf","set {n} in Documents/Dev to the name Final Plan.pdf","rename {n} from the Documents/Dev folder to Final Plan.pdf","name the file {n} in Documents/Dev Final Plan.pdf","make {n} in Documents/Dev called Final Plan.pdf"];
 for n in names {for (j,f) in rename_forms.iter().enumerate(){fresh+=1;cases.push((format!("F{fresh:03}"),f.replace("{n}",n),json!({"intent":"rename","src":{"kind":"item","name":n,"folder":"Documents/Dev"},"new_name":"Final Plan.pdf"}),format!("fresh_rename_{j}")));}}
 let zip_forms=["zip files in Documents/Dev as Toggle Wars.zip","make a zip of Documents/Dev named Toggle Wars.zip","archive the files inside Documents/Dev into Toggle Wars.zip","compress Documents/Dev files to Toggle Wars.zip","create Toggle Wars.zip from the files in Documents/Dev","put the Documents/Dev files in an archive called Toggle Wars.zip","zip up all files from Documents/Dev into Toggle Wars.zip","create a zip named Toggle Wars.zip containing Documents/Dev files","archive Documents/Dev as Toggle Wars.zip","bundle the files in Documents/Dev into Toggle Wars.zip","make Toggle Wars.zip containing files from Documents/Dev","compress all Documents/Dev files into Toggle Wars.zip"];
 for (j,f) in zip_forms.iter().enumerate(){fresh+=1;cases.push((format!("F{fresh:03}"),(*f).into(),json!({"intent":"zip","src":{"kind":"set","folder":"Documents/Dev","filter":{"type":"files"}},"output":"Toggle Wars.zip"}),format!("fresh_zip_output_{j}")));}
 let output_forms=["merge PDFs in Documents/Dev into Toggle Wars.pdf","combine PDFs from Documents/Dev as Toggle Wars.pdf","join the PDFs inside Documents/Dev into Toggle Wars.pdf","make one PDF from the PDFs in Documents/Dev called Toggle Wars.pdf","create Toggle Wars.pdf by merging PDFs in Documents/Dev","turn PDFs in Documents/Dev into one file named Toggle Wars.pdf","merge all PDFs from the Documents/Dev folder into Toggle Wars.pdf","combine all documents of type PDF in Documents/Dev to Toggle Wars.pdf","put the PDFs in Documents/Dev together as Toggle Wars.pdf","produce a merged PDF called Toggle Wars.pdf from Documents/Dev","join all files ending in PDF from Documents/Dev into Toggle Wars.pdf","make a combined PDF from Documents/Dev named Toggle Wars.pdf"];
 for (j,f) in output_forms.iter().enumerate(){fresh+=1;cases.push((format!("F{fresh:03}"),(*f).into(),json!({"intent":"merge_pdf","src":{"kind":"set","folder":"Documents/Dev","filter":{"type":"pdfs"}},"output":"Toggle Wars.pdf"}),format!("fresh_pdf_output_{j}")));}
 assert!(fresh>=120,"fresh phrase coverage");
 let (_d,roots)=fixture(); let history=History::load(roots.home.join("history.json"));let mut out=String::new();let mut counts=std::collections::BTreeMap::<String,usize>::new();
 for (id,command,expected,axis) in cases {let (actual,planner,parse_ok)=match parse(&command){Ok(i)=>{let a=canon(serde_json::to_value(&i).unwrap());let p=match Planner::new(&roots,&HashMap::new()).plan(&i,&history){Ok(Planned::Steps{actions,..})=>format!("steps:{}",actions.iter().map(action).collect::<Vec<_>>().join(";")),Ok(Planned::Info{total,..})=>format!("info:{total}"),Ok(Planned::Direct{..})=>"direct_preview_not_executed".into(),Err(Stop::Problem(m))=>format!("problem:{m}"),Err(Stop::Ambiguous{name,candidates})=>format!("ambiguous:{name}:{}",candidates.len())};(a,p,true)},Err(e)=>(json!("!"),format!("parse_refused:{e}"),false)};if id=="F001"{assert_eq!(planner,"info:1");}if id=="F049"{assert_eq!(planner,"steps:move:Project Plan.pdf:Backup");}let class=id.chars().next().unwrap_or('P');let pass=if class=='A'{true}else if class=='N'{!parse_ok}else{parse_ok&&actual==canon(expected.clone())};let guarded=!planner.starts_with("steps:");let cat=if class=='A'{"ambiguous_recorded"}else if class=='N'{if parse_ok{"accepted_negative"}else{"pass_refused"}}else if pass{"pass"}else if parse_ok&&guarded{"planner_guarded_mismatch"}else if parse_ok{"wrong_intent_or_arguments"}else{"refused"};*counts.entry(cat.into()).or_default()+=1;let row_class=if id.starts_with('F'){"new_phrase"}else if id.starts_with('X'){"targeted_phrase"}else if id.starts_with('P')||id.starts_with('K'){"control"}else{"negative_or_ambiguous"};let severity=if pass{"none"}else if parse_ok&&planner.starts_with("steps:"){"high"}else if parse_ok{"medium"}else{"low"};out.push_str(&json!({"id":id,"class":row_class,"axis":axis,"command":command,"expected":expected,"actual":actual,"parse_ok":parse_ok,"planner":planner,"category":cat,"severity":severity,"duplicate_of":null,"note":"Fixture content uses placeholder bytes; planner content validation for PDF/image operations is not asserted."}).to_string());out.push('\n');}
 // Contextual row references are resolved through scope::prepare with an actual temporary snapshot.
 let files=[roots.home.join("Downloads/report.pdf"),roots.home.join("Downloads/notes.txt"),roots.home.join("Downloads/a.pdf")];
 let snap=crate::scope::Snapshot::capture(files.to_vec(),"files in Downloads".into()).unwrap();
 for (id,command,source) in [("C001","move the first file to Backup",files[0].to_string_lossy().to_string()),("C002","copy the second one to Desktop",files[1].to_string_lossy().to_string()),("C003","trash the last file",files[2].to_string_lossy().to_string())] {
  let (actual,planner,ok)=match crate::scope::prepare(command,Some(&snap)){Ok((i,_))=>{let v=canon(serde_json::to_value(&i).unwrap());let p=match Planner::new(&roots,&HashMap::new()).plan(&i,&history){Ok(Planned::Steps{actions,..})=>format!("steps:{}",actions.iter().map(action).collect::<Vec<_>>().join(";")),Ok(Planned::Info{total,..})=>format!("info:{total}"),Ok(Planned::Direct{..})=>"direct_preview_not_executed".into(),Err(Stop::Problem(m))=>format!("problem:{m}"),Err(Stop::Ambiguous{name,candidates})=>format!("ambiguous:{name}:{}",candidates.len())};(v,p,true)},Err(e)=>(json!("!"),format!("scope_refused:{e}"),false)};
  let expected=json!({"intent":if command.starts_with("move"){"move"}else if command.starts_with("copy"){"copy"}else{"trash"},"src":{"kind":"item","name":source},"to":if command.starts_with("move"){Some("Backup")}else if command.starts_with("copy"){Some("Desktop")}else{None}});
  let expected=canon(if expected["intent"]=="trash"{json!({"intent":"trash","src":{"kind":"item","name":source}})}else{expected}); let pass=ok&&actual==expected; if id=="C001"{assert_eq!(planner,"steps:move:report.pdf:Backup");} *counts.entry(if pass{"pass"}else{"wrong_intent_or_arguments"}.into()).or_default()+=1;
  out.push_str(&json!({"id":id,"class":"contextual","axis":"row_reference","command":command,"expected":expected,"actual":actual,"parse_ok":ok,"planner":planner,"category":if pass{"pass"}else{"wrong_intent_or_arguments"},"severity":if pass{"none"}else{"high"},"duplicate_of":null,"note":"Resolved through scope::prepare against temporary snapshot."}).to_string());out.push('\n');
 }
 let report=path(OUT);fs::write(&report,out).unwrap();println!("Luna file-command audit: {} rows; {:?}; {}",counts.values().sum::<usize>(),counts,report.display());
}
